void GetGridDataByColumnLabel(wxGrid* grid, const wxString& columnLabel, int row) {
    if (!grid) return; // Ensure grid exists

    // Get column index
    int col = GetColumnIndexByLabel(grid, columnLabel);
    if (col == wxNOT_FOUND) {
        wxLogError("Column '%s' not found", columnLabel);
        return;
    }

    // Validate row index
    if (row < 0 || row >= grid->GetNumberRows()) {
        wxLogError("Invalid row index: %d", row);
        return;
    }

    // Retrieve cell value
    wxString value = grid->GetCellValue(row, col);
    wxLogMessage("Value at row %d, column '%s': %s", row, columnLabel, value);
}
